window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c6fc699ab97af95c"]={"versions": [{"id": "FIG-c6fc699ab97af95c", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Zeitverlaufs- und Timing-Diagramm im Kontext des AUTOSAR Classic Platform Treibers für die Input Capture Unit (ICU Driver, SWS_ICU_Driver). Es veranschaulicht das Zusammenspiel zwischen einem fortlaufenden 16-Bit-Freilauf-Timer (Timestamp Timer) und den an einem ICU-Kanal detektierten Signalflanken eines digitalen Eingangssignals (Input Signal) zur Erfassung von Zeitstempeln (Timestamping).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert zwei über einer gemeinsamen Zeitachse t synchronisierte Signalverläufe sowie eine zugehörige Ergebnistabelle:</p>\n<ul class=\"fig-list\"><li><strong>Timestamp Timer</strong>: Ein 16-Bit-Aufwärtszähler mit einem Wertebereich von 0 bis 0xFFFF (65535), der linear ansteigt und bei Erreichen des Maximalwerts einen Überlauf (Wrap-around / Overflow) auf 0 vollzieht.\n</li><li><strong>Input Signal</strong>: Ein digitales Eingangssignal mit den diskreten Pegeln <code>Low</code> und <code>High</code>.\n</li><li><strong>Messwerttabelle (Input Signal Level / Timestamp Timer)</strong>: Zeigt die bei jeder erkannten Signalflanke abgetasteten Werte:\n<ul class=\"fig-list\"><li>Signalpegel nach Flankenwechsel (<code>High</code> bzw. <code>Low</code>).\n</li><li>Zugehöriger Zählerstand des Timestamp Timers zum Zeitpunkt der Flankendetektion (konkrete Wertepaare: High/5461, Low/10922, High/22937, Low/32767, High/43690, Low/49151, High/58981, Low/6553).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der zeitliche Ablauf stellt die kontinuierliche Flankenerfassung im Timestamping-Betrieb dar:</p>\n<ol class=\"fig-list\"><li>Der Timestamp Timer läuft kontinuierlich aufwärts.\n</li><li>Der ICU-Kanal ist für die Detektion beider Flanken (Both Edges / <code>ICU_BOTH_EDGES</code>) konfiguriert: Jede steigende Flanke (<code>Low</code> → <code>High</code>) sowie jede fallende Flanke (<code>High</code> → <code>Low</code>) löst eine Erfassung aus.\n</li><li>Bei Auftreten einer Flanke wird der momentane Zählerstand des Timers erfasst und gemeinsam mit dem neuen Signalpegel in einen Puffer abgelegt.\n</li><li>Zwischen der siebten Flanke (High bei Zählerstand 58981) und der achten Flanke (Low bei Zählerstand 6553) tritt ein Timer-Überlauf auf: Der Zähler erreicht 0xFFFF und springt auf 0 zurück, bevor die fallende Flanke bei Stand 6553 erfasst wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt normative Relevanz für die Implementierung der ICU-Timestamping-Funktionalität (<code>Icu_StartTimestamping</code>):</p>\n<ul class=\"fig-list\"><li>Veranschaulicht die Anforderung, dass Flanken kontinuierlich erfasst und mit dem aktuellen Zählerwert korreliert werden müssen.\n</li><li>Verdeutlicht das Verhalten bei Timer-Überläufen: Da der Zähler zyklisch von 0xFFFF auf 0 überläuft, muss die auswertende Software (oder der Treiber) Differenzen unter Berücksichtigung des Modulo-2^16-Überlaufs berechnen, wenn Zeitabstände zwischen Flanken über den Überlauf hinweg bestimmt werden.\n</li><li>Bestätigt die Erfassung beider Flankenarten mit eindeutiger Zuordnung von Pegel und Zählerstand.\n</li></ul>"}, {"id": "FIG-e96f9f2d4ba577e9", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Zeitverlaufs- und Timing-Diagramm im Kontext des AUTOSAR Classic Platform Treibers für die Input Capture Unit (ICU Driver, SWS_ICU_Driver). Es veranschaulicht das Zusammenspiel zwischen einem fortlaufenden 16-Bit-Freilauf-Timer (Timestamp Timer) und den an einem ICU-Kanal detektierten Signalflanken eines digitalen Eingangssignals (Input Signal) zur Erfassung von Zeitstempeln (Timestamping).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert zwei über einer gemeinsamen Zeitachse t synchronisierte Signalverläufe sowie eine zugehörige Ergebnistabelle:</p>\n<ul class=\"fig-list\"><li><strong>Timestamp Timer</strong>: Ein 16-Bit-Aufwärtszähler mit einem Wertebereich von 0 bis 0xFFFF (65535), der linear ansteigt und bei Erreichen des Maximalwerts einen Überlauf (Wrap-around / Overflow) auf 0 vollzieht.\n</li><li><strong>Input Signal</strong>: Ein digitales Eingangssignal mit den diskreten Pegeln <code>Low</code> und <code>High</code>.\n</li><li><strong>Messwerttabelle (Input Signal Level / Timestamp Timer)</strong>: Zeigt die bei jeder erkannten Signalflanke abgetasteten Werte:\n<ul class=\"fig-list\"><li>Signalpegel nach Flankenwechsel (<code>High</code> bzw. <code>Low</code>).\n</li><li>Zugehöriger Zählerstand des Timestamp Timers zum Zeitpunkt der Flankendetektion (konkrete Wertepaare: High/5461, Low/10922, High/22937, Low/32767, High/43690, Low/49151, High/58981, Low/6553).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der zeitliche Ablauf stellt die kontinuierliche Flankenerfassung im Timestamping-Betrieb dar:</p>\n<ol class=\"fig-list\"><li>Der Timestamp Timer läuft kontinuierlich aufwärts.\n</li><li>Der ICU-Kanal ist für die Detektion beider Flanken (Both Edges / <code>ICU_BOTH_EDGES</code>) konfiguriert: Jede steigende Flanke (<code>Low</code> → <code>High</code>) sowie jede fallende Flanke (<code>High</code> → <code>Low</code>) löst eine Erfassung aus.\n</li><li>Bei Auftreten einer Flanke wird der momentane Zählerstand des Timers erfasst und gemeinsam mit dem neuen Signalpegel in einen Puffer abgelegt.\n</li><li>Zwischen der siebten Flanke (High bei Zählerstand 58981) und der achten Flanke (Low bei Zählerstand 6553) tritt ein Timer-Überlauf auf: Der Zähler erreicht 0xFFFF und springt auf 0 zurück, bevor die fallende Flanke bei Stand 6553 erfasst wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt normative Relevanz für die Implementierung der ICU-Timestamping-Funktionalität (<code>Icu_StartTimestamping</code>):</p>\n<ul class=\"fig-list\"><li>Veranschaulicht die Anforderung, dass Flanken kontinuierlich erfasst und mit dem aktuellen Zählerwert korreliert werden müssen.\n</li><li>Verdeutlicht das Verhalten bei Timer-Überläufen: Da der Zähler zyklisch von 0xFFFF auf 0 überläuft, muss die auswertende Software (oder der Treiber) Differenzen unter Berücksichtigung des Modulo-2^16-Überlaufs berechnen, wenn Zeitabstände zwischen Flanken über den Überlauf hinweg bestimmt werden.\n</li><li>Bestätigt die Erfassung beider Flankenarten mit eindeutiger Zuordnung von Pegel und Zählerstand.\n</li></ul>"}, {"id": "FIG-d38bf6eabe97b9e1", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Zeitverlaufs- und Timing-Diagramm im Kontext des AUTOSAR Classic Platform Treibers für die Input Capture Unit (ICU Driver, SWS_ICU_Driver). Es veranschaulicht das Zusammenspiel zwischen einem fortlaufenden 16-Bit-Freilauf-Timer (Timestamp Timer) und den an einem ICU-Kanal detektierten Signalflanken eines digitalen Eingangssignals (Input Signal) zur Erfassung von Zeitstempeln (Timestamping).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert zwei über einer gemeinsamen Zeitachse t synchronisierte Signalverläufe sowie eine zugehörige Ergebnistabelle:</p>\n<ul class=\"fig-list\"><li><strong>Timestamp Timer</strong>: Ein 16-Bit-Aufwärtszähler mit einem Wertebereich von 0 bis 0xFFFF (65535), der linear ansteigt und bei Erreichen des Maximalwerts einen Überlauf (Wrap-around / Overflow) auf 0 vollzieht.\n</li><li><strong>Input Signal</strong>: Ein digitales Eingangssignal mit den diskreten Pegeln <code>Low</code> und <code>High</code>.\n</li><li><strong>Messwerttabelle (Input Signal Level / Timestamp Timer)</strong>: Zeigt die bei jeder erkannten Signalflanke abgetasteten Werte:\n<ul class=\"fig-list\"><li>Signalpegel nach Flankenwechsel (<code>High</code> bzw. <code>Low</code>).\n</li><li>Zugehöriger Zählerstand des Timestamp Timers zum Zeitpunkt der Flankendetektion (konkrete Wertepaare: High/5461, Low/10922, High/22937, Low/32767, High/43690, Low/49151, High/58981, Low/6553).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der zeitliche Ablauf stellt die kontinuierliche Flankenerfassung im Timestamping-Betrieb dar:</p>\n<ol class=\"fig-list\"><li>Der Timestamp Timer läuft kontinuierlich aufwärts.\n</li><li>Der ICU-Kanal ist für die Detektion beider Flanken (Both Edges / <code>ICU_BOTH_EDGES</code>) konfiguriert: Jede steigende Flanke (<code>Low</code> → <code>High</code>) sowie jede fallende Flanke (<code>High</code> → <code>Low</code>) löst eine Erfassung aus.\n</li><li>Bei Auftreten einer Flanke wird der momentane Zählerstand des Timers erfasst und gemeinsam mit dem neuen Signalpegel in einen Puffer abgelegt.\n</li><li>Zwischen der siebten Flanke (High bei Zählerstand 58981) und der achten Flanke (Low bei Zählerstand 6553) tritt ein Timer-Überlauf auf: Der Zähler erreicht 0xFFFF und springt auf 0 zurück, bevor die fallende Flanke bei Stand 6553 erfasst wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt normative Relevanz für die Implementierung der ICU-Timestamping-Funktionalität (<code>Icu_StartTimestamping</code>):</p>\n<ul class=\"fig-list\"><li>Veranschaulicht die Anforderung, dass Flanken kontinuierlich erfasst und mit dem aktuellen Zählerwert korreliert werden müssen.\n</li><li>Verdeutlicht das Verhalten bei Timer-Überläufen: Da der Zähler zyklisch von 0xFFFF auf 0 überläuft, muss die auswertende Software (oder der Treiber) Differenzen unter Berücksichtigung des Modulo-2^16-Überlaufs berechnen, wenn Zeitabstände zwischen Flanken über den Überlauf hinweg bestimmt werden.\n</li><li>Bestätigt die Erfassung beider Flankenarten mit eindeutiger Zuordnung von Pegel und Zählerstand.\n</li></ul>"}], "trans": [{"from": "FIG-c6fc699ab97af95c", "to": "FIG-e96f9f2d4ba577e9", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e96f9f2d4ba577e9", "to": "FIG-d38bf6eabe97b9e1", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
